import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise OSError("Script path does not exist")

    is_script_path_verified = len(script_path) > 0
    process = subprocess.Popen(script_path, shell=is_script_path_verified)

    try:
        ps_process = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    total_cpu = 0.0
    total_mem = 0
    prev_mem = 0
    start_time = time.time()

    ps_process.cpu_percent()
    time.sleep(0.1)

    while True:
        if time.time() - start_time > timeout:
            process.terminate()
            break
        if process.poll() is not None:
            break

        try:
            cpu = ps_process.cpu_percent()
            mem_info = ps_process.memory_info()
            curr_mem = mem_info.rss
            if curr_mem > prev_mem:
                total_mem += (curr_mem - prev_mem)
            prev_mem = curr_mem
            total_cpu += cpu
        except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
            break

        time.sleep(0.1)

    process.wait()
    return {'CPU Usage': total_cpu, 'Memory Usage': total_mem}

